@Configuration
public class PlanchadoAutorizacionesJobConfig {

    /** 00000000-PRINCIPAL: INICIO, OPEN, PROCESO, CIERRO. */
    @Bean
    Job planchadoAutorizaciones(JobRepository repo, Step leeControl, Step planchaContratos) {
        return new JobBuilder("S500P121", repo)
                .validator(p -> {
                    // WS-PARAM-121 RECEIVED BY CONTENT: solo 1 ejecuta el planchado.
                    if (!Long.valueOf(1).equals(p.getLong("param"))) {
                        throw new JobParametersInvalidException(
                                "PARAMETRO NO RECONOCIDO " + p.getLong("param"));
                    }
                })
                .start(leeControl)          // 20000100-ABRO-BASE: lectura de B02
                .next(planchaContratos)     // 50000100-PROCESO-PLANCHADO
                .build();
    }
}

@Entity
@Table(name = "s500_b02_control")
public class ControlCaptacion {
    @Id Integer id;
    @Column(name = "ctr_autspend")    int indAutPend;       // B02-CTR-AUTSPEND
    @Column(name = "ctr_autspendeas") int indAutPendEas;    // B02-CTR-AUTSPENDEAS
    @Column(name = "fecha_lote")      LocalDate fechaLote;  // B02-FECHA-LOTE 9(8) AAAAMMDD
    @Column(name = "num_csi")         int csi;              // B02-NUM-CSI
}

@Component
@RequiredArgsConstructor
class LeeControlTasklet implements Tasklet {
    private final ControlCaptacionRepository b02;

    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        ControlCaptacion ctl = b02.findUnico()
                .orElseThrow(() -> new ProcesoAbortadoException("ERROR AL ABRIR LA BASE"));  // DMTERMINATE
        var ec = ctx.getStepContext().getStepExecution().getJobExecution().getExecutionContext();
        ec.putInt("indAutPend", ctl.indAutPend);
        ec.putInt("indAutPendEas", ctl.indAutPendEas);
        ec.putInt("csi", ctl.csi);
        return RepeatStatus.FINISHED;
    }
}

@Bean
Step planchaContratos(JobRepository repo, PlatformTransactionManager tx,
                      JpaPagingItemReader<Contrato> b03Activos,
                      PlanchadoProcessor planchado, JpaItemWriter<Contrato> b03Writer,
                      CsiValidoDecider csiValido) {
    // 50005001-APLI-DES-VDM y 50005005-APLI-DES-MTY son idénticos: un solo step.
    // CSI distinto de 04 y 10: el fuente solo despliega "NODO ERRONEO" y termina normal.
    return new StepBuilder("planchaContratos", repo)
            .<Contrato, Contrato>chunk(500, tx)
            .reader(b03Activos)
            .processor(planchado)
            .writer(b03Writer)
            .listener(new TotalesListener())          // 50100005-TOTALES
            .build();
}

@Bean
JpaPagingItemReader<Contrato> b03Activos(EntityManagerFactory emf) {
    return new JpaPagingItemReaderBuilder<Contrato>()
            .name("b03Activos")
            .entityManagerFactory(emf)
            // B03-STATUS = 0 ACTIVO, 1 BLOQUEADO; el FINDN recorre B03 completa
            .queryString("SELECT c FROM Contrato c WHERE c.status IN (0, 1) ORDER BY c.numero")
            .pageSize(500)
            .build();
}
