@Component
@StepScope
public class PlanchadoProcessor implements ItemProcessor<Contrato, Contrato> {

    @Value("#{jobExecutionContext['indAutPend']}")    private int indCorrida;
    @Value("#{jobExecutionContext['indAutPendEas']}") private int indEas;

    @Override
    public Contrato process(Contrato c) {
        if (c.ctrAutsPend() == indCorrida) {                 // ya planchado en esta corrida
            return limpiaAcumuladosSiHay(c);                  // ver s6
        }
        if (c.ctrAutsPend() == indEas) {                     // planchado por el proceso alterno
            c.marcaCorrida(indCorrida);
            c.limpiaAcumulados();
            return c;
        }
        // CONTRATO NO PLANCHADO
        if (c.autPendiente().signum() <= 0 && c.filler1().signum() <= 0 && c.filler2().signum() <= 0) {
            return null;                                      // NEXT SENTENCE: sin cambios
        }
        BigDecimal diferencia = c.filler1().subtract(c.filler2());
        c.autPendiente(diferencia.signum() > 0 ? diferencia : BigDecimal.ZERO.setScale(2));
        c.limpiaAcumulados();                                 // FILLER1 = FILLER2 = 0
        c.marcaCorrida(indCorrida);
        return c;
    }
}

    /** Ramas CONTRATO PLANCHADO (líneas 352 y 362). */
    private Contrato limpiaAcumuladosSiHay(Contrato c) {
        if (c.filler1().signum() > 0 || c.filler2().signum() > 0) {
            c.limpiaAcumulados();
            return c;                                    // se guarda (WKS-SI-B03 = 1)
        }
        return null;                                     // sin cambios: no se escribe
    }

/** S500B03CONTRATOS: campos que toca P121. */
@Entity
@Table(name = "s500_b03_contratos")
public class Contrato {
    @Id String numero;                                    // B03-NUM-CONTRATO 9(12)
    int status;                                           // 0 activo, 1 bloqueado
    @Column(precision = 14, scale = 2) BigDecimal autPendiente;   // B03-AUT-PENDIENTE
    @Column(name = "filler1", precision = 14, scale = 2) BigDecimal filler1;  // nombre heredado
    @Column(name = "filler2", precision = 14, scale = 2) BigDecimal filler2;
    int ctrAutsPend;                                      // B03-CTR-AUTSPEND
    @Version long version;                                // reemplaza LOCK / FREE
}

@Bean
JpaItemWriter<Contrato> b03Writer(EntityManagerFactory emf) {
    var w = new JpaItemWriter<Contrato>();
    w.setEntityManagerFactory(emf);
    w.setUsePersist(false);                       // STORE sobre registro existente: merge
    return w;
}
// BEGIN-TRANSACTION / STORE / END-TRANSACTIONNOAU por contrato se vuelven una transacción
// por chunk (500 contratos). Si el chunk falla, Spring Batch lo revierte completo y el
// reinicio retoma desde el último chunk confirmado; la marca B03-CTR-AUTSPEND evita
// reprocesar los contratos ya planchados.

class TotalesListener implements StepExecutionListener {
    @Override
    public ExitStatus afterStep(StepExecution s) {
        long leidosB03 = conteoB03.count();                          // todos los contratos, como el FINDN
        log.info("CONTRATOS LEIDOS {}",       leidosB03);
        log.info("CONTRATOS ACTUALIZADOS {}", s.getWriteCount());
        log.info("CONTRATOS LOCK {}",         s.getReadCount());   // estatus 0 o 1
        return s.getExitStatus();
    }
}
